// data.json의 sgroups(심리 지역) -> KB 지역코드
export const SCODE = {"전국":"0000000000","서울":"1100000000","강북":"1A0000","강남":"1B0000","6개광역시":"2A0000","5개광역시":"2B0000","부산":"2600000000","대구":"2700000000","인천":"2800000000","전남광주통합특별시":"1200000000","광주":"290000","대전":"3000000000","울산":"3100000000","세종":"3600000000","수도권":"1T0000","경기":"4100000000","강원":"5100000000","충북":"4300000000","충남":"4400000000","전북":"5200000000","전남":"460000","경북":"4700000000","경남":"4800000000","기타지방":"4A0000","제주":"5000000000"};

const iso = d => `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6, 8)}`;

async function pool(items, n, fn) {
  const out = new Array(items.length);
  let next = 0;
  await Promise.all(Array.from({ length: n }, async () => {
    while (next < items.length) { const i = next++; out[i] = await fn(items[i]); }
  }));
  return out;
}

async function call(get, path, params) {
  const j = await get(API + path + '?' + new URLSearchParams(params));
  const b = j && j.dataBody;
  if (!b || String(b.resultCode) !== '11000' || !b.data || !Array.isArray(b.data['데이터리스트']) || !Array.isArray(b.data['날짜리스트']))
    throw new Error(`KB 응답이 예상과 다릅니다: ${path} ${JSON.stringify(params)}`);
  return b.data;
}

export async function fetchWeekly(get, years = '1') {
  const out = {};
  for (const [k, [path, deal]] of Object.entries(WEEKLY)) {
    const base = { '월간주간구분코드': '02', '매물종별구분': '01', '매매전세코드': deal, '기간': years };
    const parts = await pool([null, ...SIDO], 4, c => call(get, path, c ? { ...base, '지역코드': c } : base));
    const dates = parts[0]['날짜리스트'].map(iso), by = new Map();
    for (const p of parts) {
      if (p['날짜리스트'].map(iso).join() !== dates.join()) throw new Error(`KB 응답의 날짜가 지역마다 다릅니다: ${k}`);
      for (const r of p['데이터리스트'])
        if (!by.has(r['지역코드'])) by.set(r['지역코드'], { name: r['지역명'], vals: r.dataList.slice(0, dates.length) });
    }
    out[k] = { dates, by };
  }
  return out;
}

export async function fetchMarket(get, years = '1') {
  const out = {};
  for (const [k, [menu, fields]] of Object.entries(MARKET)) {
    const d = await call(get, 'maktTrnd', { '메뉴코드': menu, '월간주간구분코드': '02', '기간': years });
    const dates = d['날짜리스트'].map(iso), by = new Map();
    for (const r of d['데이터리스트']) {
      const rows = new Map(r.dataList.map(x => [iso(String(x['기준날짜'])), x]));
      by.set(r['지역코드'], { name: r['지역명'], vals: dates.map(dt => { const x = rows.get(dt); return fields.map(f => x ? x[f] : null); }) });
    }
    out[k] = { dates, by };
  }
  return out;
}

const num = (v, mul) => typeof v === 'number' && isFinite(v) ? Math.round(v * mul) : null;

function sameDates(set, label) {
  const ks = Object.keys(set), d0 = set[ks[0]].dates.join();
  for (const k of ks) if (set[k].dates.join() !== d0) throw new Error(`KB 응답의 날짜가 항목마다 다릅니다(${label}): ${k}`);
  return set[ks[0]].dates;
}

function newDates(have, got, label) {
  const last = have[have.length - 1], add = got.filter(d => d > last);
  if (add.length && !got.includes(last))
    throw new Error(`${label}: 현재 데이터(${last})와 KB 응답(${got[0]}~) 사이에 빈 주차가 있습니다. 관리자 페이지에서 엑셀을 한 번 올려 주세요.`);
  return add;
}

export async function updateData(D, get) {
  const w = await fetchWeekly(get), m = await fetchMarket(get);

  const wd = sameDates(w, '시계열'), weeks = newDates(D.dates, wd, '시계열');
  for (const d of weeks) {
    const at = wd.indexOf(d), nat = w.mae.by.get(CODE['전국']);
    if (!nat || typeof nat.vals[at] !== 'number') throw new Error(`${d} 주차의 전국 값이 아직 없습니다.`);
  }
  for (const k of Object.keys(WEEKLY))
    D.names.forEach((n, i) => {
      const s = CODE[n] ? w[k].by.get(CODE[n]) : null;
      for (const d of weeks) D[k][i].push(s ? num(s.vals[wd.indexOf(d)], 1000) : null);
    });
  D.dates.push(...weeks);

  const sd = sameDates(m, '심리'), sweeks = newDates(D.sdates, sd, '심리');
  for (const k of Object.keys(MARKET))
    D.sgroups.forEach((g, i) => {
      const s = SCODE[g] ? m[k].by.get(SCODE[g]) : null;
      for (const d of sweeks) {
        const v = s ? s.vals[sd.indexOf(d)] : [null, null, null];
        for (let q = 0; q < 3; q++) D[k][i][q].push(num(v[q], 100));
      }
    });
  D.sdates.push(...sweeks);

  return { weeks, sweeks, last: D.dates[D.dates.length - 1] };
}
